// Local speech only. Groq receives text via the existing assistant after Send.
let worker=null,sequence=0,pending=new Map(),context=null,source=null,capture=null,stream=null,timer=null,frames=[],samples=0,player=null,playbackDone=null,epoch=0;
const state={ready:false,busy:false,recording:false,autoSpeak:true,status:'Local voice off · English',revision:0,transcript:'',transcriptId:0};
const $=id=>document.getElementById(id);
function update(values={}){Object.assign(state,values);state.revision++;$('voice-status').textContent=state.status;$('voice-enable').disabled=state.busy||state.recording||state.ready;$('voice-talk').disabled=!state.ready||state.busy;$('voice-talk').textContent=state.recording?'Finish recording':'Talk';$('voice-auto').checked=state.autoSpeak;}
function getWorker(){if(worker)return worker;worker=new Worker(new URL('./voice-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data:d})=>{const p=pending.get(d.id);if(!p)return;if(d.progress){update({status:d.progress});return;}clearTimeout(p.timeout);pending.delete(d.id);d.error?p.reject(Error(d.error)):p.resolve(d.result);};worker.onerror=()=>{for(const p of pending.values()){clearTimeout(p.timeout);p.reject(Error('Speech worker failed. Try Enable voice again.'));}pending.clear();worker?.terminate();worker=null;update({ready:false,busy:false,status:'Speech engine failed; text chat remains available.'});};return worker;}
function run(op,extra={}){return new Promise((resolve,reject)=>{const id=++sequence;const w=getWorker();const timeout=setTimeout(()=>{stop();update({status:'Speech timed out. Try again or use text chat.'});},300000);pending.set(id,{resolve,reject,timeout});w.postMessage({id,op,...extra},extra.audio?[extra.audio.buffer]:[]);});}
async function audioContext(){context??=new AudioContext();await context.resume();return context;}
function closeMic(){clearTimeout(timer);timer=null;if(capture){capture.port.onmessage=null;capture.disconnect();capture=null;}source?.disconnect();source=null;stream?.getTracks().forEach(t=>t.stop());stream=null;}
function silence(){playbackDone?.();playbackDone=null;if(player){player.onended=null;try{player.stop();}catch{}player=null;}}
function stop(){epoch++;closeMic();silence();frames=[];samples=0;worker?.terminate();worker=null;for(const p of pending.values()){clearTimeout(p.timeout);p.reject(new DOMException('Stopped','AbortError'));}pending.clear();update({ready:false,busy:false,recording:false,status:'Stopped · Enable voice to resume (cached models reused)'});}
async function enable(){if(state.busy||state.ready)return;const token=++epoch;update({busy:true,status:'Preparing local speech…'});try{await audioContext();const mic=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});mic.getTracks().forEach(t=>t.stop());if(token!==epoch)return;await run('load');if(token===epoch)update({ready:true,busy:false,status:'Ready · tap Talk, then Finish (max 20 seconds)'});}catch(e){if(token===epoch)update({busy:false,ready:false,status:'Voice unavailable: '+e.message});}}
async function toggle(){if(state.recording)return finish();if(!state.ready||state.busy)return;const token=++epoch;silence();update({busy:true,status:'Opening microphone…'});try{const ctx=await audioContext();await ctx.audioWorklet.addModule(new URL('./voice-capture.js',import.meta.url));const mic=await navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true},video:false});if(token!==epoch){mic.getTracks().forEach(t=>t.stop());return;}stream=mic;frames=[];samples=0;source=ctx.createMediaStreamSource(stream);capture=new AudioWorkletNode(ctx,'voice-capture',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1]});capture.port.onmessage=({data})=>{if(state.recording){frames.push(data);samples+=data.length;}};source.connect(capture);capture.connect(ctx.destination);update({recording:true,busy:false,status:'Listening locally · tap Finish when done'});timer=setTimeout(finish,20000);}catch(e){closeMic();if(token===epoch)update({busy:false,recording:false,status:'Microphone error: '+e.message});}}
async function finish(){if(!state.recording)return;const token=epoch;closeMic();update({recording:false,busy:true,status:'Transcribing locally…'});try{if(samples<context.sampleRate*.25)throw Error('Recording too short. Please try again.');const pcm=new Float32Array(samples);let off=0;for(const f of frames){pcm.set(f,off);off+=f.length;}frames=[];let energy=0;for(const f of pcm)energy+=f*f;if(Math.sqrt(energy/pcm.length)<.001)throw Error('No speech detected. Please try again.');const offline=new OfflineAudioContext(1,Math.ceil(samples*16000/context.sampleRate),16000);const b=offline.createBuffer(1,samples,context.sampleRate);b.copyToChannel(pcm,0);const s=offline.createBufferSource();s.buffer=b;s.connect(offline.destination);s.start();const rendered=await offline.startRendering();if(token!==epoch)return;const result=await run('transcribe',{audio:new Float32Array(rendered.getChannelData(0))});if(token!==epoch)return;const text=result.text?.trim();if(!text)throw Error('No words recognized. Please try again.');$('ai-input').value=text;update({busy:false,transcript:text,transcriptId:state.transcriptId+1,status:'Review the transcript, then press Send.'});}catch(e){if(token===epoch)update({busy:false,status:e.message});}}
async function speak(text){if(!state.ready||state.busy||state.recording||!text)return;const token=++epoch;silence();update({busy:true,status:'Generating local voice (first use downloads Kokoro)…'});try{await audioContext();const clean=String(text).replace(/[`#*_]/g,'').slice(0,1600);const chunks=clean.match(/[^.!?]+[.!?]*\s*/g)||[clean];for(const part of chunks){for(let i=0;i<part.length;i+=240){if(token!==epoch)return;const clip=await run('speak',{text:part.slice(i,i+240)});if(token!==epoch)return;const buffer=context.createBuffer(1,clip.audio.length,clip.sampleRate);buffer.copyToChannel(clip.audio,0);player=context.createBufferSource();player.buffer=buffer;player.connect(context.destination);update({status:'Speaking locally…'});await new Promise(resolve=>{playbackDone=resolve;player.onended=()=>{playbackDone=null;resolve();};player.start();});}}if(token===epoch)update({busy:false,status:String(text).length>1600?'Spoken first 1,600 characters; full answer is in chat.':'Ready · tap Talk to ask another question'});}catch(e){if(token===epoch)update({busy:false,status:'Speech error: '+e.message});}}
function latest(){const messages=window.CognitiveAssistant?.state().messages||[];return [...messages].reverse().find(m=>m.role==='assistant')?.text||'';}
function toggleAuto(){state.autoSpeak=!state.autoSpeak;update();}
window.CognitiveVoice={state:()=>({...state}),enable,toggle,stop,speakLatest:()=>speak(latest()),toggleAuto,onAnswer:text=>{if(state.autoSpeak&&state.ready&&!state.busy)speak(text);}};
$('voice-enable').onclick=enable;$('voice-talk').onclick=toggle;$('voice-stop').onclick=stop;$('voice-read').onclick=()=>speak(latest());$('voice-auto').onchange=()=>{state.autoSpeak=$('voice-auto').checked;update();};
window.addEventListener('pagehide',stop);
window.addEventListener('message',e=>{if(e.source===$('viewer').contentWindow&&e.origin===location.origin&&e.data?.type==='viewer-loaded'&&(state.ready||state.busy||state.recording))stop();});
update();
